fn is_prime(n: i8) -> bool {
    // According to the problem specification, 
    // primality is only defined for integers >= 2.
    // For any n < 2, return false.
    if n < 2 {
        return false;
    }

    // Check divisors k in [2, n-1].
    // If any divides n, return false immediately.
    //
    // Invariants maintained during the loop:
    // - n >= 2 (true throughout)
    // - candidate divisor k in [2, n]
    // - For all j with 2 <= j < k, n % j != 0
    //
    // Termination measure:
    // - measure = n - k, which strictly decreases each iteration.
    //
    // If loop terminates with no divisor found, n is prime.
    
    let mut k: i8 = 2;

    while k < n {
        if n % k == 0 {
            return false; // divisor found
        }
        k += 1;
    }

    true // no divisors found, n is prime by definition
}